#!/bin/bash
# get-ai-router.sh — one-file bootstrap for free-tier-ai-router.
#
# Why this exists: the ClawHub registry entry for this skill is frozen at 1.6.1
# (newer versions publish successfully but never appear). This script installs
# the package, then upgrades it to the current, fully-fixed router.
#
#   bash get-ai-router.sh [API_KEY]
set -u
KEY="${1:-}"
DEST="${AI_ROUTER_DIR:-$HOME/.ai-router}"
mkdir -p "$DEST"
echo "🎛️  installing free-tier-ai-router -> $DEST"
if command -v npx >/dev/null 2>&1; then
  (cd "$DEST" && npx --yes clawhub@latest install free-tier-ai-router --no-input >/dev/null 2>&1) \
    && echo "  ✅ base package installed" || echo "  ⚠️  registry install failed; continuing"
fi
SK="$DEST/skills/free-tier-ai-router"
mkdir -p "$SK"
# The upgrade payload travels WITH this script (appended below the marker).
awk '/^#__PAYLOAD__
{
 "_comment": "self-repair payload for integrate.sh",
 "sha256": "acbf88f77ec522fcf9d635f0ea9ab6926071712fd3c7dcb7913d99e5bb1fb229",
 "router_py_b64": ""
}
